// In-process: cheap, transactional, atomic.
// This is why you start here.
@Transactional
public Order placeOrder(OrderRequest req) {
  inventory.reserve(req.items());      // direct call, same TX
  Order order = orders.save(req);      // rolls back together on failure
  payments.charge(order);              // throws -> everything rolls back
  return order;
}
